INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('970a9f21-3e9c-441b-a5f4-ddac0a08c1ee', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek$q$, $q$Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "a57379df-1ecc-44ce-bf82-4e1e9adfd826", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "190126b4-4cb4-4b7c-8ae0-2c70a95368e8", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "71054b54-0d9d-457c-bb1d-5f285d463874", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "9c85dd53-04c6-4eaf-881e-c51c92c3b38b", "text": "Igaz", "isCorrect": true}, {"id": "58effcf4-9554-47e2-a52b-d6818d66c966", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "049101f6-7969-4b62-ad6f-446b9994b82a", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "df287190-4754-41c9-bf93-9ae4c4540f59", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "fafeafc5-eb8b-40fe-9796-e96f55f71e38", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "4b44d765-3db3-4247-a0bd-d74df0f796de", "text": "Igaz", "isCorrect": true}, {"id": "2b1b6abf-dc2c-44a8-bb46-16e1169a44b2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "50ad0ece-0551-4f12-9c2c-60497d94a60f", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "bc2121cb-8af6-4968-99e3-dd09cf938484", "text": "Igaz", "isCorrect": true}, {"id": "fe7d4cc7-bd35-4d1c-9baf-9b446ed52ce4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7918db2a-7d75-4a39-b233-9eb49e6e40f0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.$q$, $q$Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "a015d409-a969-42fd-8cca-997b755f6f41", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "39db85fb-df71-424a-afa6-7ba05e3a5fcf", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e0bb1bb7-e42e-4041-bec4-de2a4d2fbd11", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "688eb397-7acc-45f2-b34d-9c002449b129", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "24cc64dd-6b02-4e08-9edd-fb3b4e7ae06d", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "72392b00-4cb1-41e5-ad3c-b3735a0afd58", "text": "Igaz", "isCorrect": true}, {"id": "f49a41b6-22bc-483e-9f9f-c8be4a2783bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c18def35-1016-4d35-9a25-c3f628f4b6b0", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "acb0100c-c827-411e-8b66-1b2ed23826b6", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "26f15700-7da4-441f-b0a4-7e3b3db87d8d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2180c6ff-7b48-4292-9496-e2823ee1eb0b", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('15dff298-99bb-4ed8-bdd7-35432f492c4f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$63. óra: Szerkesztési feladatok$q$, $q$Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "02f487b0-0d02-4148-b755-1e59cdd5907d", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "a2c66cc4-b4f5-4b79-bafc-886c01fcac99", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "f4a3ffcb-4828-4758-8654-a714f97e3089", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "eefb7494-3b55-412f-b499-5ec44b9f0f3b", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "bc50732c-dc4c-4031-8f72-2aeef306a032", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "59d7863a-dfe0-4479-8f6d-a7b133d56a83", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "c7d4314a-3596-423f-8de0-6896318e7fd1", "text": "Igaz", "isCorrect": true}, {"id": "97d77670-6a7b-4d6f-a81b-34540d942379", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f18b01b-3b54-42a4-a00e-b77cd380dee1", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "138923b1-3830-466b-b4b4-4fc5e7b6231d", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "c8292799-a999-4dde-9f9d-d799a2afbb03", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "5ed5fcc8-5928-4c68-bc07-1ad46d0cc765", "text": "Igaz", "isCorrect": true}, {"id": "2d78f01b-5412-4ecc-a49a-f38dd758d0ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d7e2e6f1-d4ac-4820-8193-26a133fa5bda", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "35f3de3a-1559-47fd-b2c6-065911dc7c2b", "text": "Igaz", "isCorrect": true}, {"id": "7bb5dd60-487f-4446-9ac5-41247504bca0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1c089113-becc-4ffe-a7b4-181c51c972ec", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "bd7c0821-5a32-4e00-8ffe-fd11ecca0226", "text": "Igaz", "isCorrect": true}, {"id": "f5a994d4-492a-4265-afd8-19bc34580f37", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8f973bbc-f162-4d1a-95dd-23ef02d5b73f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$64. óra: Dinamikus szerkesztőprogram megismerése$q$, $q$Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "ece710ca-443d-401d-8b81-2b02c59cddcd", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "385eb925-a1c6-493c-9bea-2897d45a99cb", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "1f981594-44e1-4fc0-af34-1f6e0c9b8997", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "0c1b0e39-c8b5-4c33-92a1-b81fc8af77be", "text": "Videóvágásra", "isCorrect": false}, {"id": "b9c74bb7-a122-467e-8104-8a38011fa975", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "30649cb7-3b98-4197-834d-b162e6ca50c9", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "d35080e8-7343-450d-a01c-97680fbca145", "text": "Igaz", "isCorrect": true}, {"id": "c68f99a7-5999-4c1c-a9c7-eaee98f28108", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e1d88a0a-9ecf-493c-9ffc-6ec6cba1d030", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "e07feda2-de3d-41cc-8e01-409b0dad0968", "text": "Igaz", "isCorrect": true}, {"id": "67555a46-121c-4ebb-9ff1-633fe08adb08", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d6004c95-2905-42a6-8269-95eb0040a51d", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "606fc180-4ee3-4155-aa3d-96f0b9ca93b3", "text": "Igaz", "isCorrect": true}, {"id": "9f817807-c903-4976-8fd2-1eb77641fb18", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5faf0678-dedb-4632-86a5-375d66c8492c", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "58820ff9-2505-4cf6-ad5c-3491f75a4943", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "e2c3f7aa-1085-4bfe-9b3b-7048cd893b19", "text": "Színezés", "isCorrect": false}, {"id": "f3ac6d3e-0e45-4127-ae0c-6a083ee08f5c", "text": "Törlés", "isCorrect": false}, {"id": "b03d7e80-bb94-44f1-b030-c400adf7c19b", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "17af8f46-e3fc-471c-ac80-ed9618d2e9f8", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "cafcd834-c934-44e4-a2dd-301b9aaf8187", "text": "Igaz", "isCorrect": true}, {"id": "8cf2ac70-a0d3-485e-8572-347e1d1d92fb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18083ee7-91d8-4e93-8376-da7ec3b96870", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('994c572d-f7df-48a6-838d-dcb3eb2ba610', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$65. óra: Összefoglalás$q$, $q$A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "722195bd-05fa-4b0b-9d8d-2d8f24464450", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f66b8822-254b-4846-81dd-9b8d02812ebe", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "2622ef64-33c4-43a3-85d4-4f909fe79ed6", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "3952014c-b393-4cb8-a8a2-95832997e064", "text": "Igaz", "isCorrect": true}, {"id": "fd312667-8849-4659-8cad-386f714d8bf0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d63cda6c-b71b-4028-bf49-262bfc6dea02", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "ebdd8db1-e072-4655-9aa7-f02b55648267", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "a5f07fae-be21-43fd-88df-ae405fcd9c35", "text": "Igaz", "isCorrect": true}, {"id": "1fd01119-ae11-4af6-9ea9-74241dc08d0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f0b1d308-ed2c-4694-8bc8-1c742e20fcae", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "9a190e5e-5078-4e26-ad12-fa57af42f860", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "8d56ea42-a8c0-491c-b169-03e1b3fafe26", "text": "Igaz", "isCorrect": true}, {"id": "fb99cca0-108f-4f05-a5e5-5c3e9509814d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c76fca27-3e88-4a6f-8a52-a11aa1844255', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$66. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "7f09ba05-d0af-4e81-900c-b761963b410b", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "8ae28d1f-ef49-4578-81ce-646791f07ebe", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "36296f6a-3565-446f-8636-6b8ab33b4d6f", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "494fee03-8cd4-412a-afe5-74a6a16c2690", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "cd922786-936c-41e7-9f92-a81cd788b911", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "3b4bbb55-d81a-4f08-840e-d98dc83b4e29", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "627b2f93-89be-4f37-bb29-345708e389fe", "text": "Igaz", "isCorrect": true}, {"id": "19b0e0d1-3956-46d4-ade7-83fcdc725789", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8d4855e-d4dd-4978-9126-e601f197eec4", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "87b4371c-d42c-4388-b12e-3e647a8dc2a0", "text": "Igaz", "isCorrect": false}, {"id": "4b109fae-3a4f-4649-8252-9518b1a5272a", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "3b10de1d-e95a-41f3-ab77-8d05e49f0ffd", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "a4ef2a82-f64e-4d10-8451-f630d1b27aec", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "11c09334-3229-4b34-a888-bbf6cfa97cc9", "text": "Igaz", "isCorrect": true}, {"id": "032d7f0e-72a4-4805-93bc-d121eef27435", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d22dfdd-c758-462a-885c-277e27cd80ef", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "4ff6b8c0-2511-4219-8132-995e0bdf0447", "text": "Önmagában", "isCorrect": true}, {"id": "52a80955-2191-4cc4-b16f-386701ab5687", "text": "Az origóban", "isCorrect": false}, {"id": "16f588bc-4bfd-46a7-9fee-7f537d40ce64", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "6646f0fa-0684-4f21-8fa5-58eefb40da18", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1dd3155b-0d7b-4c4a-8094-f77d343d914a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$67. óra: Témazáró dolgozat értékelése$q$, $q$A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "5dc88659-cb73-456d-8560-8019b8e3d2af", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "79eda9c3-f365-47f4-839b-2eea5513c558", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "0f6caa41-e0df-4545-af65-26792672cc53", "text": "A ceruza színe", "isCorrect": false}, {"id": "1bd7b224-840e-443a-ad3f-bb2f9f274fe1", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "a5ff9889-9961-45eb-af49-aae4b50fed2b", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "8492605f-411a-4bec-9a26-a86f65ccb48c", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "c244d861-f65e-43a7-9dd3-463190e9a963", "text": "Igaz", "isCorrect": true}, {"id": "e8c2d467-a71c-4796-8a02-5e7f945aadae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8d96a386-a72a-450f-9cbc-819d3965c713", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "2d87cc0d-bcc6-47e1-97bb-b12c1b9070cf", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "5603c3b5-056b-4448-9424-9fca76b0792c", "text": "Igaz", "isCorrect": true}, {"id": "3e3dcfd7-0619-4e52-a250-b7ba680c4d99", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60d0a9ef-aa15-4559-b60b-c73da7094a03", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "6f0dbea8-f4bc-4fc5-bfc3-f068c8cde872", "text": "Végtelen sok", "isCorrect": true}, {"id": "61a235f1-e362-45ba-acc4-caa1efbed876", "text": "1", "isCorrect": false}, {"id": "2eb2abc4-244f-45fb-8394-a56134fb2467", "text": "2", "isCorrect": false}, {"id": "b315fd44-1ea8-4e81-9fe0-36842a637e21", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "360e1229-6753-402a-9064-50da9f2414be", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "64be53d0-f6e8-4fa0-8544-1a027a6b5550", "text": "Igaz", "isCorrect": true}, {"id": "37c7cb3e-9892-4bfb-8a78-1f3b0f8c743e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "609bb1f6-44f0-469b-9059-f7c16ccd68f4", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ae2c8204-df70-456c-9f54-9c87b377d5bc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$68. óra: Az arány fogalma$q$, $q$Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "3da69b5d-2658-4190-87f1-d77986f8a165", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "930ae317-8465-4dcd-8eed-f83dea2d50fc", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "a18d82ff-0583-4b84-bcf4-2c0fea0a2172", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "955d434b-6c57-48e6-baa6-b78447886927", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "3aeb6928-ba89-4276-9398-5d5dd1d37719", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "79c18e00-3713-4d0e-8f9a-2771cb107ec8", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "bbe6ad68-3946-425a-a5e2-d0d013c45cf6", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "98b726ec-fee0-42f1-a835-fdaeea4455e4", "text": "Plusz jellel", "isCorrect": false}, {"id": "9c49d5b6-15d2-4554-a2e0-332ef025bd3c", "text": "Csillaggal", "isCorrect": false}, {"id": "46a24f73-283b-4580-a127-5076bfae49f5", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "1c649f51-ac13-4eda-a090-cec52a11beba", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "0a158991-2c68-451a-80a5-a26240cd1be8", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "d6489104-9772-46a5-9893-8fee47df3811", "text": "1 : 2", "isCorrect": false}, {"id": "8e33b011-f489-4f44-b6bd-5fb5a64d8456", "text": "3 : 2", "isCorrect": false}, {"id": "75db4445-e051-4ec4-b1a0-e0b3bde55183", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "d5a42277-26e7-4ccc-83e1-82201950d4a1", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "bd4cffa0-bd48-4fa2-a507-a0f77cb1ea76", "text": "Igaz", "isCorrect": true}, {"id": "4ee1ac83-8926-4433-9998-2c81b5549241", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "af9729c3-3e95-4ae2-b465-e6f7e0f12041", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "e1d55a95-a9e9-4ef1-a28a-9ab8e21d65e7", "text": "1 : 2", "isCorrect": true}, {"id": "daac9f48-a5ab-469a-a958-e0c1d57ae520", "text": "2 : 4", "isCorrect": false}, {"id": "acfdcd89-e25a-4955-bada-1cf04680c6dd", "text": "1 : 4", "isCorrect": false}, {"id": "7226e3df-2228-4fc6-9809-c8ccf29fef0c", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "b7f0602f-0cd7-46ee-b42d-11c7b679f95c", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "6b4f42f3-73c5-40c0-8c97-3fc36ba0439f", "text": "Igaz", "isCorrect": true}, {"id": "17713695-3546-4426-9a63-fc731bfb2898", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5cd9088e-984f-45b4-9851-64c05bb95265", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "52c21ee5-f8a8-48ea-9c0d-ed3c3727cbdf", "text": "5 : 10", "isCorrect": true}, {"id": "51df01c5-ace9-4cbd-b726-416584c3d0ca", "text": "2 : 1", "isCorrect": false}, {"id": "032fae5b-bb9d-40fb-ae53-8d0654e0fe8b", "text": "3 : 5", "isCorrect": false}, {"id": "54a0b27d-6bbb-4e04-a12a-e277b8511183", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dcf6eecf-60c1-4503-bbd4-ef707dba8505', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$69. óra: Arányos osztás$q$, $q$Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "72220691-4be8-44fe-bd2e-5e2c75c86ce5", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0d6aa34c-3dfd-48b3-b5a4-ffa10615a13e", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "bc5da318-864e-4194-a3fb-5ea0a8b7666a", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "5dff77f4-e80e-4ed8-afd3-04a47075583f", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "3c1e257f-6393-46da-a625-786e54a01e6c", "text": "Igaz", "isCorrect": true}, {"id": "5af3fde9-0413-430a-bf96-e51bbb7336e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8e6243a1-f541-4b2f-902d-1ca78ef7844e", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c2e0cf6c-cacf-4114-a4a8-7f3d580b6e5f", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "a0d18ff4-6919-4880-87fd-42aa849c5578", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "d59d74ff-5929-4340-b211-ec7eeba90f84", "text": "Igaz", "isCorrect": true}, {"id": "fdcf69da-0f6a-47ab-9106-85da2ebe8e20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5ffedf57-b7ec-4e05-8ba6-6425cdb4cf9d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$70. óra: Feladatok megoldása$q$, $q$Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "25c1f0c9-e514-4eb9-9c4f-67409e621584", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "8b5f3415-323c-4bb8-a8cc-08308b7cb877", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "d18b74c1-51ae-4e74-8e06-6bad8be8a5f7", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "462b2acb-593b-4086-89ae-c7ede5329c51", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "c2d395d6-b091-48b7-b82e-77c2151d577c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b8c5642-c71d-4179-addd-1becd0ee8517", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "9f8c596e-af9a-4b6b-a4bb-a5cb9af664ae", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "543bd2c3-09ce-4c7f-a33b-846b4e1170ea", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "461c2e76-f935-49ae-a715-6a85663eadb0", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "3e97e199-20fb-4abe-99d1-2b2cc2e1de1f", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "e7994033-d39b-4e7c-a7e6-96c6003f8cb8", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "027dd055-b45b-424c-b761-3f3439659954", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e825f50a-c280-443a-ae0d-3ac74a6f59f3", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "11c83e42-3016-40de-8022-a0c161758601", "text": "Igaz", "isCorrect": true}, {"id": "228dfebd-f0fc-4ef9-8ec7-ca90bd254aab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;